function resolveSpaceDragon(choice) {
  document.getElementById('spaceDragonOverlay').classList.add('hidden');
  send({type:'joker_power',power:'space',choice});
  addLog(choice==='change'?'🌌 Space Dragon: seat order changed!':'🌌 Space Dragon: held position.','imp');
