function showPortalModal(msg) {
  const btns=document.getElementById('portalBtns');
  btns.innerHTML='';
  (msg.valid_target_pids||[]).forEach(pid=>{
    const btn=document.createElement('button');
    btn.className='btn btn-outline btn-full';
    btn.style.cssText='border-color:#00CED1;color:#40E0D0;';
    btn.textContent=`🎯 Steal from ${nameOf(pid)}`;
    btn.onclick=()=>{
      document.getElementById('portalOverlay').classList.add('hidden');
      send({type:'portal_target',target_pid:pid});
      addLog(`🌀 Portal: stealing from ${nameOf(pid)}...`,'imp');
    };
    btns.appendChild(btn);
  });
  document.getElementById('portalOverlay').classList.remove('hidden');
}

function showLoveModal(msg) {
  const btns=document.getElementById('loveBtns');
  btns.innerHTML='';
  (msg.tamer_pids||[]).forEach(pid=>{
    const btn=document.createElement('button');
    btn.className='btn btn-outline btn-full';
    btn.style.cssText='border-color:#FF69B4;color:#FFB6C1;';
    btn.textContent=`💕 Give lead to ${nameOf(pid)}`;
    btn.onclick=()=>{
      document.getElementById('loveOverlay').classList.add('hidden');
      send({type:'princess_choose_tamer',tamer_pid:pid});
      addLog(`💕 Love Power: ${nameOf(pid)} earns next lead!`,'imp');
    };
    btns.appendChild(btn);
  });
  document.getElementById('loveOverlay').classList.remove('hidden');
}

