let _roundEndTimer=null;
function showRoundEndOverlay(msg) {
  const overlay=document.getElementById('roundEndOverlay');
  const title=document.getElementById('roundEndTitle');
  const rowsEl=document.getElementById('roundEndRows');
  const timerEl=document.getElementById('roundEndTimer');
  rowsEl.innerHTML='';

  const winnerPid=msg.winner_pid||null;
  title.textContent=winnerPid
    ? `Round ${msg.round||''} — ${nameOf(winnerPid)} wins!`
    : `Round ${msg.round||''} Complete!`;

  const order=(gameState?.order)||Object.keys(gameState?.players||{});
  order.forEach(pid=>{
    const p=gameState?.players?.[pid]; if(!p||p.out) return;
    const d=p.dragon_count||0;
    const dragonStr=d>0?'🐉'.repeat(Math.min(d,5))+(d>5?`+${d-5}`:''):'—';
    const row=document.createElement('div');
    row.className='round-end-row'+(pid===winnerPid?' winner-row':'');
    row.innerHTML=`<span class="round-end-name">${pid===myPid?'👤 '+p.name:p.name}${pid===winnerPid?' 🏆':''}</span>`+
      `<span class="round-end-dragons">${dragonStr} <span style="font-size:11px;color:rgba(253,246,227,.45);">(${d})</span></span>`;
    rowsEl.appendChild(row);
  });

  let secs=5;
  timerEl.textContent=`Auto-closing in ${secs}s…`;
  overlay.classList.remove('hidden');
  _roundEndTimer=setInterval(()=>{
    secs--;
    if(secs<=0){ dismissRoundEnd(); }
    else { timerEl.textContent=`Auto-closing in ${secs}s…`; }
  },1000);
}
function dismissRoundEnd() {
  if(_roundEndTimer){ clearInterval(_roundEndTimer); _roundEndTimer=null; }
  document.getElementById('roundEndOverlay').classList.add('hidden');
  hideBattle();
}

