function showSpaceDragonModal(msg) {
  const btns=document.getElementById('spaceDragonBtns');
  btns.innerHTML='';
  (msg.valid_target_pids||[]).forEach(pid=>{
    const btn=document.createElement('button');
    btn.className='btn btn-outline btn-full';
    btn.style.cssText='border-color:#9B59B6;color:#C39BD3;';
    btn.textContent=`🔄 Swap seats with ${nameOf(pid)}`;
    btn.onclick=()=>resolveSpaceDragon(pid);
    btns.appendChild(btn);
  });
  if(msg.can_pass){
    const passBtn=document.createElement('button');
    passBtn.className='btn btn-outline btn-full';
    passBtn.style.cssText='border-color:rgba(253,246,227,.2);color:rgba(253,246,227,.4);';
    passBtn.textContent='✗ Stay in current seat';
    passBtn.onclick=()=>resolveSpaceDragon(null);
    btns.appendChild(passBtn);
  }
  document.getElementById('spaceDragonOverlay').classList.remove('hidden');
}
function resolveSpaceDragon(targetPid) {
  document.getElementById('spaceDragonOverlay').classList.add('hidden');
  send({type:'space_dragon_swap', target_pid: targetPid||null});
  addLog(targetPid?`🌌 Space Dragon: swapping with ${nameOf(targetPid)}!`:'🌌 Space Dragon: staying put.','imp');
}

