ws.onopen  = () => {
  _connecting=false;
  _reconnectAttempts=0;
  setConnStatus(true,'Connected');
  if(myPid && myRoomId && !_rejoining) {
    _rejoining=true;
    setConnStatus(true,'Reconnecting...');
    send({type:'rejoin', pid:myPid, room_id:myRoomId});
  }
  // Keep-alive: ping every 25s so the connection doesn't silently drop
  if(_heartbeatTimer){ clearInterval(_heartbeatTimer); _heartbeatTimer=null; }
  _heartbeatTimer=setInterval(()=>{
    if(ws && ws.readyState===WebSocket.OPEN){
      try{ ws.send(JSON.stringify({type:'ping'})); }catch(e){}
    } else {
      clearInterval(_heartbeatTimer); _heartbeatTimer=null;
    }
  }, 25000);
};
ws.onclose = () => {
  _connecting=false;
  _rejoining=false;
  if(_heartbeatTimer){ clearInterval(_heartbeatTimer); _heartbeatTimer=null; }
  setConnStatus(false,'Disconnected \u2014 retrying...');
  scheduleReconnect();
};

