function setSuit(s) {
  selectedSuit=s;
  const map={Hearts:'suitH',Clubs:'suitC',Diamonds:'suitD',Spades:'suitS'};
  document.querySelectorAll('.suit-btn').forEach(b=>b.classList.remove('active'));
  const target=document.getElementById(map[s]);
  if(target) target.classList.add('active');
  if(phase==='leader_declare' && gameState?.lead_pid===myPid) renderSuitFlush(s);
}
function renderSuitFlush(suit) {
  const el=document.getElementById('suitFlushPreview');
  if(!el) return;
  const hand=gameState?.me?.hand||[];
  const isRed=suit==='Hearts'||suit==='Diamonds';
  const cards=hand.filter(c=>c&&!c.is_joker&&c.suit===suit);
  cards.sort((a,b)=>(b.rank||0)-(a.rank||0));
  if(!cards.length){
    el.innerHTML=`<span class="flush-label">No ${SUIT_SYM[suit]||suit} cards in hand</span>`;
    el.classList.remove('hidden'); el.classList.add('flush-visible'); return;
  }
  const sym=SUIT_SYM[suit]||'';
  const chips=cards.map(c=>{
    const rankStr=(c.label||'').replace(/[♥♣♦♠]/g,'');
    let cls='flush-chip';
    if(c.is_dragon) cls+=' fc-dragon';
    else if(c.is_tamer) cls+=' fc-tamer';
    else if(isRed) cls+=' fc-r';
    const badge=c.is_dragon?' 🐉':c.is_tamer?' 🧙':'';
    return `<span class="${cls}">${rankStr}${sym}${badge}</span>`;
  }).join('');
  el.innerHTML=`<span class="flush-label">${cards.length}×${sym}</span>${chips}`;
  el.classList.remove('hidden'); el.classList.add('flush-visible');
}

