  const curRound=gameState?.round||1;
  const curRank=PHASE_ORDER[phase]??0;
  const snapRank=PHASE_ORDER[snapPhase]??0;
  // Snapshot is stale if: same round but earlier phase, OR earlier round
  const snapIsStale = (snapRound < curRound) ||
                      (snapRound === curRound && snapRank < curRank);
  if(snapIsStale){
    addLog('\uD83D\uDD04 Reconnected','imp');
