    if(msg.state.phase)   gameState.phase=msg.state.phase;
    if(msg.state.round!=null) gameState.round=msg.state.round;
    if(msg.state.declared_steps!=null) gameState.declared_steps=msg.state.declared_steps;
    if(msg.state.declared_el)  gameState.declared_el=msg.state.declared_el;
    if(msg.state.lead_pid)     gameState.lead_pid=msg.state.lead_pid;
    const snap_me=msg.state.me||msg.state.players?.[myPid];
    if(snap_me) gameState.me=snap_me;
  }
  _awaitingRoundEndContinue=true;
  _roundEndOverlayVisible=true;
  document.getElementById('roundEndOverlay').classList.remove('hidden');
  const _mb=document.getElementById('mainBtn');
  if(_mb){ _mb.textContent='CONTINUE TO NEXT ROUND \u25b6'; _mb.disabled=false; }
  setConnStatus(true,'Reconnected');
  addLog('\uD83D\uDD04 Reconnected to game','imp');
  break;
}
